This is my workaround:

```cs
extension(Transform3D Transform3D) {
    public Transform3D WithGlobalScale(Vector3 NewGlobalScale) {
        Transform3D NewTransform3D = Transform3D;

        Basis RotationBasis = NewTransform3D.Basis.Orthonormalized();
        NewTransform3D.Basis = RotationBasis.Scaled(NewGlobalScale);

        return NewTransform3D;
    }
    public void SetGlobalScale(Vector3 NewGlobalScale) {
        Basis RotationBasis = Transform3D.Basis.Orthonormalized();
        Transform3D.Basis = RotationBasis.Scaled(NewGlobalScale);
    }
}
```
